/* ============================================================
   Test-data reset + seed for a DSA dev database.

   DESTRUCTIVE: clears every case table (Skolebegynder, its changes,
   Sagsaktivitet, SkoleHistorik, Foraelder, Elev, Adresse, PortalAuditLog)
   and inserts a fictional cohort of skolebegyndere. Lookups are NOT
   touched — run seed_lookup_data.sql first.

   All names, CPR numbers and address ids are made up. The addresses are
   real Aarhus streets with invented numbers and GUIDs; nothing here links a
   person to a place.

   What the cohort covers — 106 children, 109 cases, generated by a script
   (deterministic) and kept as plain SQL. Expected after step 7:

     @skoleaar       Potentiel skolestarter   5 \ Ikke screenet tab (16)
                     Tid booket              11 /
                     Screening afviklet      47 \  (also its own tab)
                     Skoleplaceret           24  > Overblik tab (85)
                     Afsluttet               14 /
     @skoleaar - 1   Afsluttet                8
     Ændringer       21 rows, 18 unhandled (Ændringer tab), all seven årsager

     - the 15 original children (Amira, Tomas, ...) unchanged
     - children whose school start was postponed ("Skolegangsudsat") last
       year and who are skolebegyndere again this year — the reason Skolebegynder
       has its own id rather than CPR as key
     - booked screenings still to come, a few no-shows and interrupted
       screenings (all "Tid booket"), PPR cases and children recently
       moved to DK
     - a second skoleønske on ~40% of the children, and an afklaring note on
       the screened children PUF has not assessed yet
     - siblings and twins sharing custody holders and address
     - two name- and address-protected children, one with a father who must
       not know the address
     - offers at a secondary campus, a specialklasse, and cases where district
       school, wanted school and offer differ (skoler_afviger)

   Skoleskiftere og tilflyttere (migrations 004-005, draft), 34 cases shaped
   like the OS2Forms submissions, expected after step 7: Ny 7, Afventer
   sprogvurdering 6, Aftalt sprogscreening 4, Sendt til PPR 3, Afventer
   skoletilbud 6, Skoletilbud afsendt 4, Afsluttet 4 (two on a passed offer
   date, two on "Alderssvarende dansk"). 13 straight from modtagelsesklasse,
   21 through the school's form; two families with two children.

   Dates are not hardcoded: every date, school year and child's birth year
   is derived from the run date (see "Datoankre" in step 2), as in
   befordringssystemet's seed. Run in October 2026, @skoleaar is 2027.

   The screening data follows a real SX export (2026-10-23): samlet_resultat
   is Alderssvarende dansk / Sprogstøttebehov / Nærmere afklaring, or
   "Ej sprogscreenet" (with zero scores) for a child SX has not screened —
   which the status rule treats as not screened; ordforråd has 19 items and
   sprogforståelse 15; percentiles have one decimal; ordforråd's score is the
   number correct ("uden bonus"), sprogforståelse's adds a bonus. The numbers
   themselves are made up. puf_screeningsresultat is not in the SX export and
   remains ILLUSTRATIVE.

   Statuses are not hand-set except Afsluttet: the cases are inserted as
   "Potentiel skolestarter" and usp_recalculate_skolebegynder_status derives the rest,
   so this file also exercises the status rule.

   Requires migration 001, seed_lookup_data.sql (including Skolematrikel),
   the views and the stored procedure usp_recalculate_skolebegynder_status.

   Runs inside a transaction that ROLLBACKs by default — change the final
   ROLLBACK to COMMIT once the previewed data looks correct.
   ============================================================ */

USE [DSA];

SET NOCOUNT ON;
SET XACT_ABORT ON;


/* ------------------------------------------------------------
   SERVERSPÆRRE — udfyld @tilladte_servere før scriptet bruges

   Som i befordringssystemet: USE [DSA] siger intet om hvilken server man
   står på, og det eneste andet værn er ROLLBACK'et nederst — som pointen er,
   at man laver om til COMMIT.

   Fejler LUKKET: kun servere på listen nedenfor er tilladt. Servernavnet
   skrives som en VÆRDI i INSERT'et — kolonnen hedder servernavn og skal
   blive ved med det. Find navnet med:   SELECT @@SERVERNAME;
------------------------------------------------------------ */

DECLARE @tilladte_servere TABLE (servernavn SYSNAME);

INSERT INTO @tilladte_servere (servernavn) VALUES
    -- (N'MIN-DEV-SERVER'),
    (N'SRVSQL58');

IF NOT EXISTS (SELECT 1 FROM @tilladte_servere WHERE servernavn = @@SERVERNAME)
BEGIN
    RAISERROR(
        'STOPPET: seed_test_data sletter ALLE sagsdata og maa ikke koere paa %s. Tilfoej servernavnet til @tilladte_servere, hvis det er en testserver.',
        16, 1, @@SERVERNAME
    );
    RETURN;
END;

PRINT CONCAT('Serverspaerre OK: ', @@SERVERNAME);


IF OBJECT_ID(N'[dsa].[usp_recalculate_skoleskifter_status]', N'P') IS NULL
BEGIN
    RAISERROR('STOPPET: dsa.usp_recalculate_skoleskifter_status findes ikke. Koer migration 004 og stored_procedures foerst.', 16, 1);
    RETURN;
END;

IF COL_LENGTH(N'dsa.Skoleskifter', N'skoleaar') IS NULL
BEGIN
    RAISERROR('STOPPET: dsa.Skoleskifter mangler kolonnerne fra migration 005. Koer 005_skoleskifter_formular.sql foerst.', 16, 1);
    RETURN;
END;


IF OBJECT_ID(N'[dsa].[usp_recalculate_skolebegynder_status]', N'P') IS NULL
BEGIN
    RAISERROR('STOPPET: dsa.usp_recalculate_skolebegynder_status findes ikke. Koer stored_procedures foerst.', 16, 1);
    RETURN;
END;


BEGIN TRANSACTION;


/* ------------------------------------------------------------
   1. Clear case data — children before parents
------------------------------------------------------------ */

DELETE FROM [dsa].[Skolebegynder_Aendring];
DELETE FROM [dsa].[Sagsaktivitet];
DELETE FROM [dsa].[Skolebegynder];
DELETE FROM [dsa].[Skoleskifter];
DELETE FROM [dsa].[SkoleHistorik];
DELETE FROM [dsa].[Foraelder];
DELETE FROM [dsa].[Elev];
DELETE FROM [dsa].[Adresse];
DELETE FROM [dsa].[PortalAuditLog];

PRINT 'Cleared case data.';


/* ------------------------------------------------------------
   2. Lookup ids, by name
------------------------------------------------------------ */

DECLARE @fagomraade_sb INT = (
    SELECT fagomraade_id FROM [dsa].[Fagomraade] WHERE fagomraade_tekst = N'Skolebegynderscreeninger');

DECLARE @status_potentiel INT = (
    SELECT status_id FROM [dsa].[Status]
    WHERE status_tekst = N'Potentiel skolestarter' AND fagomraade_id = @fagomraade_sb);
DECLARE @status_afsluttet INT = (
    SELECT status_id FROM [dsa].[Status]
    WHERE status_tekst = N'Afsluttet' AND fagomraade_id = @fagomraade_sb);

IF @fagomraade_sb IS NULL OR @status_potentiel IS NULL OR @status_afsluttet IS NULL
   OR NOT EXISTS (SELECT 1 FROM [dsa].[Skolematrikel])
   OR NOT EXISTS (SELECT 1 FROM [dsa].[Skoletilbudstype])
   OR NOT EXISTS (SELECT 1 FROM [dsa].[Aendringsaarsag])
   OR NOT EXISTS (SELECT 1 FROM [dsa].[SagsaktivitetType])
BEGIN
    ROLLBACK TRANSACTION;
    RAISERROR('STOPPET: opslagsdata mangler. Koer seed_lookup_data.sql foerst.', 16, 1);
    RETURN;
END;

-- School offers, skoletilbudstyper, ændringsårsager and activity types are
-- referenced by their TEXT below and joined to the lookups, so this file
-- does not depend on the ids seed_lookup_data.sql happened to assign.


/* ============================================================
   Datoankre
   ------------------------------------------------------------
   As in befordringssystemet's seed: every date below is derived from
   GETDATE() rather than written as a literal, so the data does not decay —
   a file with fixed dates shows last year's cohort, with screenings and
   letters that look a year old, once the calendar has moved on.

   The data is a snapshot of a cohort mid-season, measured back from the
   day the seed is run: the list was drawn ~6 months ago, screenings
   happened 7-14 weeks ago, school offers were given in the following
   weeks and the first cases closed in the last two weeks. The offsets are
   relative to the run date, not to the real screening calendar (Jan-Feb).

   @skoleaar is the cohort being worked on: the children starting school
   next August — this year before August, next year from August on.
   Children are born @skoleaar - 6 (postponed children a year earlier);
   @cpr_aar_skift moves the birth year in the fictional CPR numbers, which
   are written below for the 2026 cohort.
============================================================ */

DECLARE @i_dag date      = CAST(GETDATE() AS date);
DECLARE @nu    datetime2 = CAST(CAST(GETDATE() AS date) AS datetime2);

DECLARE @skoleaar int =
    CASE WHEN MONTH(@i_dag) >= 8 THEN YEAR(@i_dag) + 1 ELSE YEAR(@i_dag) END;

DECLARE @cpr_aar_skift int = @skoleaar - 2026;


/* ------------------------------------------------------------
   3. Addresses (fictional numbers and ids)  — 147 rows
------------------------------------------------------------ */

