/* ------------------------------------------------------------
   5. Skolebegynder cases — 109 cases

   All inserted as "Potentiel skolestarter" except the closed ones; the procedure in
   step 7 derives every other status from the data. The school offer is
   given as the campus NAME and the skoletilbudstype as its TEXT, joined to
   the lookups here.
------------------------------------------------------------ */

INSERT INTO [dsa].[Skolebegynder]
