    ON st.skoletilbudstype_tekst = v.tilbud_type;

PRINT CONCAT('Skolebegynder: ', @@ROWCOUNT, ' row(s).');

-- Every named campus and type must have resolved; a typo would otherwise
-- silently leave a case without its offer.
DECLARE @antal_skoletilbud INT = (
    SELECT COUNT(*) FROM [dsa].[Skolebegynder]
    WHERE skoletilbud_matrikel_id IS NOT NULL AND skoletilbudstype_id IS NOT NULL);

IF @antal_skoletilbud <> 46
BEGIN
    ROLLBACK TRANSACTION;
    RAISERROR('STOPPET: et skoletilbud i testdata kunne ikke slaas op (matrikelnavn eller skoletilbudstype).', 16, 1);
    RETURN;
END;


