JOIN [dsa].[Skolebegynder] sb ON sb.cpr = STUFF(v.cpr, 5, 2, RIGHT(CONCAT('0', CAST(SUBSTRING(v.cpr, 5, 2) AS INT) + @cpr_aar_skift), 2)) AND sb.skoleaar = v.skoleaar
JOIN [dsa].[SagsaktivitetType] t ON t.type_kode = v.type_kode;

PRINT 'Sagsaktivitet seeded.';



/* ------------------------------------------------------------
   6b. Skoleskiftere og tilflyttere (migrations 004-005, draft) — 34 cases

   Shaped like the OS2Forms submissions (backend/db/formulars): only cases
   that reach DSA. 13 straight from the parents (modtagelsesklasse), the rest through
   the receiving school's form. 14 tilflyttere, 11 skoleskift internt,
   9 skoleskift udefra; two families with two children each. Manual
   statuses, and cases closed on "Alderssvarende dansk", are inserted as
   such; the rest as "Ny" for the procedure in step 7. The assessment
   results and the ESDH numbers are made up.
------------------------------------------------------------ */

DECLARE @fagomraade_ss INT = (
    SELECT fagomraade_id FROM [dsa].[Fagomraade] WHERE fagomraade_tekst = N'Skoleskiftere og tilflyttere');

INSERT INTO [dsa].[Skoleskifter]
    (cpr, variant, status_id, modtaget_tidspunkt,
     os2forms_id, ansoegningsdata, esdh_noegle,
     skoleaar, nuvaerende_skoletilbud, udslusningsdato, nuvaerende_kommune,
     oensket_skolekode, nuvaerende_skolekode, nuvaerende_skole_tekst, klassetrin_ansoegning,
     flytning, flyttedato, kommende_adresse, modersmaal_foraelder, modersmaal_skole,
     soeskende_paa_skolen, soeskende_klasse, begrundelse, skolens_afgoerelse,
     screeningsdato, point_1, resultat_1, point_2, resultat_2, point_3, resultat_3, samlet_resultat,
     skoletilbud_matrikel_id, skoletilbudstype_id, dato_skoletilbud, start_visitationsklasse, klassetrin, spor,
     bemaerkning, ppr_sendt_dato, afsluttet_dato, created_by, updated_by)
SELECT
    STUFF(v.cpr, 5, 2, RIGHT(CONCAT('0', CAST(SUBSTRING(v.cpr, 5, 2) AS INT) + @cpr_aar_skift), 2)), v.variant, st.status_id, v.modtaget,
    v.os2forms_id, v.ansoegningsdata, v.esdh_noegle,
    v.skoleaar, v.nuvaerende_skoletilbud, v.udslusningsdato, v.nuvaerende_kommune,
    v.oensket_skolekode, v.nuvaerende_skolekode, v.nuvaerende_skole_tekst, v.klassetrin_ansoegning,
