         oensket_skolekode, nuvaerende_skolekode, nuvaerende_skole_tekst, klassetrin_ansoegning,
         flytning, flyttedato, kommende_adresse, modersmaal_foraelder, modersmaal_skole,
         soeskende_paa_skolen, soeskende_klasse, begrundelse, skolens_afgoerelse,
         screeningsdato, p1, r1, p2, r2, p3, r3, samlet_resultat,
         tilbud_matrikel, tilbud_type, dato_skoletilbud, start_visitationsklasse, klassetrin, spor,
         bemaerkning, ppr_sendt_dato, afsluttet_dato)
JOIN [dsa].[Status] st
    ON st.status_tekst = v.status AND st.fagomraade_id = @fagomraade_ss
LEFT JOIN [dsa].[Skolematrikel] sm
    ON sm.matrikel_navn = v.tilbud_matrikel
LEFT JOIN [dsa].[Skoletilbudstype] stt
    ON stt.skoletilbudstype_tekst = v.tilbud_type;

PRINT CONCAT('Skoleskifter: ', @@ROWCOUNT, ' row(s).');

-- The submissions hold the child's CPR, the dates and the school year as
-- placeholders; fill them in from the row, so they match the shifted columns.
UPDATE [dsa].[Skoleskifter]
SET    ansoegningsdata =
           REPLACE(REPLACE(REPLACE(REPLACE(ansoegningsdata,
               N'__CPR__', cpr),
               N'__SKOLEAAR__', CONCAT(skoleaar, N'/', skoleaar + 1)),
               N'__FLYTTEDATO__', COALESCE(CONVERT(CHAR(10), flyttedato, 23), N'')),
               N'__UDSLUSNING__', COALESCE(CONVERT(CHAR(10), udslusningsdato, 23), N''))
WHERE  created_by = N'Testdata';

-- One "Sag oprettet" per case (the case log is keyed by CPR).
INSERT INTO [dsa].[Sagsaktivitet]
    (cpr, aktivitetstype, kommentar, udfoert_af, oprettet_tidspunkt, fagomraade_id, relateret_sag_id, aktivitetstype_id)
SELECT ss.cpr, N'Sag oprettet', CONCAT(N'Ansøgning modtaget via OS2Forms (', ss.variant, N')'), N'System',
       ss.modtaget_tidspunkt, @fagomraade_ss, ss.skoleskifter_id, t.type_id
FROM   [dsa].[Skoleskifter] ss
JOIN   [dsa].[SagsaktivitetType] t ON t.type_kode = N'sag_oprettet';


/* ------------------------------------------------------------
   7. Derive statuses — exercises the status rule
------------------------------------------------------------ */

EXEC [dsa].[usp_recalculate_skolebegynder_status] @today = @i_dag;
EXEC [dsa].[usp_recalculate_skoleskifter_status] @today = @i_dag;


/* ------------------------------------------------------------
   8. Preview — runs before the COMMIT/ROLLBACK decision
------------------------------------------------------------ */

SELECT status_tekst, COUNT(*) AS antal
FROM   [dsa].[view_Skolebegyndere]
GROUP BY status_tekst, status_sortering
ORDER BY status_sortering;

SELECT skolebegynder_id, skoleaar, navn, status_tekst, distriktsskole, oensket_skole,
       skoletilbud_matrikel, skoletilbudstype_tekst, skoler_afviger, aabne_aendringer
FROM   [dsa].[view_Skolebegyndere]
ORDER BY skoleaar, status_sortering, navn;

SELECT * FROM [dsa].[view_Skolebegynder_Aendringer] ORDER BY registreret_tidspunkt;


SELECT variant, indgang, status_tekst, COUNT(*) AS antal
FROM   [dsa].[view_Skoleskiftere]
GROUP BY variant, indgang, status_tekst, status_sortering
ORDER BY variant, indgang, status_sortering;


-- Change to COMMIT once the preview above looks right.
ROLLBACK TRANSACTION;
-- COMMIT TRANSACTION;
